Bun.serve({port:Number(Bun.env.PORT||3000),async fetch(req){const url=new URL(req.url);if(url.pathname==='/health')return new Response('ok');if(url.pathname==='/engine-test'){try{const test=extendedProfile(new URLSearchParams({birth:'1990-06-15',time:'14:30',offset:'-05:00',lat:'40.7128',lon:'-74.0060'}));const pass=Object.fromEntries(['western','vedic','human','genekeys'].map(k=>[k,!!test[k]]));return new Response('<!doctype html><html lang="en"><meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:system-ui;background:#111b17;color:#d5ee9b;padding:24px"><h1>Open-source engines · test profile</h1><p>Sample: 1990-06-15 14:30 UTC-05 · New York</p><pre style="white-space:pre-wrap">'+JSON.stringify({pass,calculated:test,version:'GIT BUILD 02'},null,2).replace(/</g,'&lt;')+'</pre></body></html>',{headers:{'content-type':'text/html; charset=utf-8'}})}catch(e){return new Response('<h1>Engine error</h1><pre>'+String(e.message||e).replace(/</g,'&lt;')+'</pre>',{status:500,headers:{'content-type':'text/html'}})}}if(url.pathname==='/api/extended-profile'){try{const params=req.method==='POST'?new URLSearchParams(Object.entries(await req.json()).filter(([k,v])=>typeof v==='string'&&['birth','time','zone','offset','lat','lon'].includes(k)).map(([k,v])=>[k,v.slice(0,80)])):url.searchParams;return Response.json(extendedProfile(params),{headers:{'cache-control':'no-store'}})}catch(e){return Response.json({error:String(e.message||e)},{status:400})}}if(url.pathname==='/api/self-test'){const tests=[];const pass=(name,fn)=>{try{const value=fn();tests.push({name,ok:!!value})}catch(e){tests.push({name,ok:false,error:String(e.message||e).slice(0,180)})}};pass('moon_sun_bazi_huangli',()=>{const z=snapshotCurrent('2026-11-07','20:00',-480);return z.moon.phase>=0&&z.moon.phase<=360&&z.sun.sign&&z.bazi.day&&Array.isArray(z.almanac.yi)});pass('vedic_western_human_genekeys',()=>{const r=extendedProfile(new URLSearchParams({birth:'1990-06-15',time:'14:30',offset:'-05:00',lat:'40.7128',lon:'-74.0060'}));return ['western','vedic','human','genekeys'].every(k=>r[k]&&!r.errors[k])});pass('qimen_tibetan',()=>{const r=daySystems('2026-11-07','21:00');return r.qimen?.chiefDoor&&r.tibetan?.day>0&&!Object.keys(r.errors).length});pass('invalid_birth_rejected',()=>{try{strictBirth('1990-13-45','28:99');return false}catch{return true}});return Response.json({version:'GIT BUILD 10',ok:tests.every(x=>x.ok),tests},{headers:{'cache-control':'no-store'}})}if(url.pathname==='/api/day-systems'){try{return Response.json(daySystems(url.searchParams.get('date')||new Date().toISOString().slice(0,10),url.searchParams.get('time')||'12:00'))}catch(e){return Response.json({error:String(e.message||e)},{status:400})}}if(url.pathname==='/api/date-batch'){try{const dates=(url.searchParams.get('dates')||'').split(',').slice(0,35),offset=url.searchParams.get('offset')||'0';return Response.json({days:dates.map(date=>({date,...snapshotCurrent(date,'12:00',offset)}))})}catch(e){return Response.json({error:String(e.message||e)},{status:400})}}if(url.pathname==='/api/snapshot'){try{return Response.json(snapshotCurrent(url.searchParams.get('date')||new Date().toISOString().slice(0,10),url.searchParams.get('time')||'12:00',url.searchParams.get('offset')||'0'))}catch(e){return Response.json({error:String(e.message||e)},{status:400})}}if(url.pathname==='/api/natal'){try{return Response.json(natalData(url.searchParams.get('birth')||'',url.searchParams.get('time')||'',url.searchParams.get('offset')||''))}catch(e){return Response.json({error:String(e.message||e)},{status:400})}}
if(url.pathname==='/api/bazi'){try{const tm=url.searchParams.get('time')||'12:00';return Response.json(baziData(url.searchParams.get('birth')||'',tm,url.searchParams.has('time')))}catch(e){return Response.json({error:String(e.message||e)},{status:400})}}if(url.pathname==='/api/ai'&&req.method==='POST'){try{const input=await req.json();if(typeof input.key!=='string'||!input.key.startsWith('gsk_'))return Response.json({error:'Нужен действующий Groq API key.'},{status:400});const entries=Array.isArray(input.entries)?input.entries.slice(-30).map(e=>({date:String(e.date||'').slice(0,40),text:String(e.text||'').slice(0,3000)})):[];const goals=Array.isArray(input.goals)?input.goals.slice(0,30).map(g=>String(g).slice(0,150)):[];const question=String(input.question||'Проведи анализ повторяющихся паттернов.').slice(0,500);const system='Ты аналитик личного дневника. Отвечай на русском, точно и без психологических диагнозов. Разделяй наблюдения, гипотезы, ограничения и возможные действия. Не утверждай, что астрология или нумерология научно предсказывают исходы. Указывай, когда записей мало. Не выдумывай факты.';const prompt=JSON.stringify({question,goals,entries});const resp=await fetch('https://api.groq.com/openai/v1/chat/completions',{method:'POST',headers:{'Authorization':'Bearer '+input.key,'Content-Type':'application/json'},body:JSON.stringify({model:'openai/gpt-oss-120b',messages:[{role:'system',content:system},{role:'user',content:prompt}],temperature:0.35,max_tokens:1100})});const payload=await resp.json();if(!resp.ok)return Response.json({error:payload.error?.message||'Ошибка Groq: '+resp.status},{status:resp.status});return Response.json({answer:payload.choices?.[0]?.message?.content||'Модель не вернула ответ.'})}catch(e){return Response.json({error:'Не удалось выполнить анализ.'},{status:500})}}if(url.pathname==='/api/periods'){try{const month=url.searchParams.get('month')||new Date().toISOString().slice(0,7),tz=url.searchParams.get('tz')||'UTC';if(!/^20\d\d-(0[1-9]|1[0-2])$/.test(month))return new Response('Invalid month',{status:400});return Response.json({events:eventsFor(month,tz),timeZone:tz})}catch(e){return Response.json({error:String(e)},{status:500})}}return new Response(html,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'}})}});